MOVES = {0: (-1, 0), 1: (1, 0), 2: (0, -1), 3: (0, 1)}
BLOCKING = (WALL, LAMP_OFF, LAMP_ON, OOB)
MEMORY = 8


def predict(context_frames, context_actions, future_actions):
    """Dead-reckon the agent, keep a map of every cell seen, render futures from the map."""
    cells, pos = {}, (0, 0)

    def see(frame, t):
        for i, row in enumerate(frame):
            for j, value in enumerate(row):
                if (i, j) != (2, 2):
                    cells[(pos[0] + i - 2, pos[1] + j - 2)] = (value, t)

    def lookup(cell, t):
        value = cells.get(cell)
        return value[0] if value and (MEMORY is None or t - value[1] <= MEMORY) else FLOOR

    def move(action, t):
        nonlocal pos
        pos = (pos[0] + MOVES[action][0], pos[1] + MOVES[action][1])

    see(context_frames[0], 0)
    for t, action in enumerate(context_actions, 1):
        move(action, t)
        see(context_frames[t], t)
    frames, t = [], len(context_actions)
    for action in future_actions:
        t += 1
        move(action, t)
        frame = [
            [AGENT if (i, j) == (2, 2) else lookup((pos[0] + i - 2, pos[1] + j - 2), t) for j in range(5)]
            for i in range(5)
        ]
        see(frame, t)
        frames.append(frame)
    return frames

